<template><a-card :bordered="false"><template #title><a-space><span>审计日志</span><a-tag color="blue">平台</a-tag></a-space></template><template #extra><a-button @click="load">刷新</a-button></template><a-space class="filters" wrap><a-input v-model:value="filters.keyword" allow-clear placeholder="事件类型关键字" style="width:240px" @press-enter="load"/><a-input v-model:value="filters.aggregateType" allow-clear placeholder="聚合类型" style="width:180px"/><a-input v-model:value="filters.aggregateId" allow-clear placeholder="聚合 ID" style="width:280px"/><a-button type="primary" @click="load">查询</a-button></a-space><a-table v-resizable-columns row-key="eventId" :data-source="logs" :columns="columns" :loading="loading" :pagination="{pageSize:20,showSizeChanger:false}"><template #bodyCell="{column,record}"><template v-if="column.key==='source'"><a-tag :color="record.source==='OUTBOX'?'green':'purple'">{{record.source}}</a-tag></template><template v-else-if="column.key==='status'"><a-tag :color="record.status==='PUBLISHED'?'green':record.status==='FAILED'?'red':'orange'">{{record.status||'-'}}</a-tag></template><template v-else-if="column.key==='occurredAt'">{{formatTime(record.occurredAt)}}</template></template></a-table></a-card></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{message}from'ant-design-vue';import{auditApi}from'../../api/audit';import type{AuditLogEntry}from'../../types/audit';const loading=ref(false);const logs=ref<AuditLogEntry[]>([]);const filters=reactive({keyword:'',aggregateType:'',aggregateId:''});const columns=[{title:'来源',key:'source',width:90},{title:'事件类型',dataIndex:'eventType',key:'eventType',width:220},{title:'聚合类型',dataIndex:'aggregateType',key:'aggregateType',width:140},{title:'聚合 ID',dataIndex:'aggregateId',key:'aggregateId',width:260},{title:'状态',key:'status',width:100},{title:'尝试',dataIndex:'attempts',key:'attempts',width:70},{title:'说明',dataIndex:'message',key:'message'},{title:'发生时间',key:'occurredAt',width:190}];async function load(){loading.value=true;try{logs.value=await auditApi.search({keyword:filters.keyword.trim()||undefined,aggregateType:filters.aggregateType.trim()||undefined,aggregateId:filters.aggregateId.trim()||undefined,limit:300})}catch(e){message.error((e as Error).message)}finally{loading.value=false}}function formatTime(v:string){return v?new Date(v).toLocaleString():'-'}onMounted(load)</script><style scoped>.filters{margin-bottom:16px}</style>